from review import card,save,DATE
i='TCS-3787';_,c=card(i);refs=c['references'];refs[0]['locator']='Sections 2–3 define compression, shattering and ampleness; Theorem 10 treats maximum classes; abstract and discussion leave the ample extension open.'
refs += [dict(id='journal',title='Unlabeled Sample Compression Schemes and Corner Peelings for Ample and Maximum Classes',authors='Jérémie Chalopin; Victor Chepoi; Shay Moran; Manfred K. Warmuth',year=2022,url='https://doi.org/10.1016/j.jcss.2022.01.003',pdf_url='https://arxiv.org/pdf/1812.02099v2',locator='JCSS 127 (August 2022), 1–28; full preprint revised 5 January 2022, Section 2 page 5 explicitly requires proper reconstruction; Section 3 and Theorem 5.1; abstract retains the ample question.'),dict(id='oriented',title='Unlabeled Sample Compression Schemes for Oriented Matroids',authors='Tilen Marc',year=2024,url='https://doi.org/10.1016/j.disc.2024.114006',pdf_url='https://arxiv.org/pdf/2203.11535v4',locator='Discrete Mathematics 2024; full revision 7 March 2024; Theorem 3.1, affine extension, and Corollary 3.5 for COMs with corner peelings. Section on proper compression and corner peeling explicitly says the ample question remains open.')]
notes=['Recovered the exact VC-dimension bound for every finite ample class.','Read the full journal-version definition to restore proper reconstruction into the original class, not arbitrary total labelings.','Defined all realizable partial samples, two maps, unlabeled unordered stored subsets and the absence of side information or efficiency requirements.','Separated labeled compression, maximum classes, representation maps and corner peelings; removed the suggested geometric solution route.','Checked the 2024 oriented-matroid result, which explicitly retains the general ample question.']
save(i,dict(title='Proper unlabeled compression of ample classes',formal='Does every nonempty ample concept class C⊆{0,1}ᵁ on a finite domain U admit a proper unlabeled sample compression scheme of size at most d=VC(C)? Precisely, do there exist maps κ:RS(C)→{A⊆U:|A|≤d} and ρ:{A⊆U:|A|≤d}→C such that, for every realizable labeled partial sample s, κ(s)⊆dom(s) and ρ(κ(s)) agrees with every label in s? The stored object is only an unordered subset of the sample’s input points. The bound is d, not an unspecified multiple of d.',definitions='A concept c∈C is a function c:U→{0,1}. A set A⊆U is shattered by C if {c|_A:c∈C}={0,1}ᴬ. It is strongly shattered if some b:U∖A→{0,1} has the property that, for every a:A→{0,1}, the combined labeling a∪b belongs to C. Thus strong shattering requires a full cube of concepts with identical labels outside A. The class is ample when every shattered set is strongly shattered; ample classes are also called lopsided or shattering-extremal. Its VC dimension d is the maximum size of a shattered set. A labeled partial sample is a function s:A→{0,1} on some A⊆U, equivalently a set of pairs (x,s(x)) with distinct x. It is realizable if s=c|_A for some c∈C; RS(C) contains every such sample, including the empty sample. The compressor κ sees the entire labeled sample and may use its labels to choose a subset κ(s) of its domain, of size at most d. It sends only that subset. The reconstructor ρ receives no labels, ordering, multiplicities, sample size, omitted sample points or auxiliary bits; U,C,κ and ρ are fixed and shared beforehand. It returns a total concept belonging to C, which must agree with the original entire sample, including omitted labels. This is the proper convention explicitly used in the full source. Requiring ρ on all subsets of size at most d is equivalent to defining it only on Im(κ), because C is nonempty and unused inputs can be assigned any fixed concept. The existence of κ,ρ is quantified separately for each finite C; no running-time bound for constructing or evaluating them, distributional assumption or probability of error is part of the statement. For d=0 a nonempty class has a single concept and the empty compressed set suffices. A maximum class of dimension d has cardinality Σ_{j=0}^d binomial(|U|,j); every maximum class is ample, but the converse need not hold.',question_type='yes_no',answer_criterion='Prove existence of the two maps with the stated d-point bound for every finite nonempty ample class, or give an ample class with a proof that no such pair of maps exists. A scheme retaining labels, returning a hypothesis outside C, storing extra information, or exceeding d points does not meet the target. A scheme that handles only full concepts rather than every realizable partial sample is also insufficient. Failure of a proposed corner-peeling construction alone does not refute existence of a compression scheme.',context_blocks=[dict(title='Maximum classes already satisfy the sharp bound',text='The source constructs proper unlabeled schemes of size d for maximum classes. Its open extension concerns all ample classes, a strictly larger family.',citation='journal'),dict(title='Labeled and unlabeled compression differ',text='Size-d labeled compression is already known for ample classes. The new requirement is that the reconstructor recover a consistent concept from selected input points after all their labels have been removed.',citation='journal'),dict(title='A failed structural conjecture is not a compression counterexample',text='The source exhibits a maximum class of VC dimension three without a corner, refuting earlier corner-peeling arguments. It nevertheless proves the compression theorem for maximum classes. The absence of corners therefore does not imply the desired maps do not exist.',citation='journal'),dict(title='Later results cover further structured classes',text='The 2024 paper proves proper unlabeled schemes for oriented matroids and for complexes of oriented matroids admitting corner peelings. It explicitly states that the general ample-class question remains open.',citation='oriented')],why='Would extend sharp label-free sample compression from maximum classes to the larger class characterized by equality of shattering and strong shattering, clarifying how far the VC dimension controls lossless reconstruction of consistent samples.',references=refs,progress=[dict(date='2019',text='The source corrects earlier corner-peeling claims, proves size-d unlabeled compression for maximum classes and asks for an ample-class extension.',citation='primary'),dict(date='2022',text='The journal treatment explicitly uses proper reconstruction and retains the ample extension as open.',citation='journal'),dict(date='2024',text='Proper unlabeled compression is proved for additional oriented-matroid classes, while the general ample question is explicitly retained.',citation='oriented')],status='open',status_note='Read the full proper-compression definition and the distinction between maximum and ample classes, then checked the 2024 oriented-matroid theorem and its explicit remaining-question paragraph. Also checked the revised labeled-compression work for complexes of oriented matroids, whose retained labels make its result different. Searches through 12 September 2026 found no resolution for every finite ample class; searches are not exhaustive.',model_self_contained=True,requires_context=False,review_note='The full source resolves the proper/improper convention. The card asks for arbitrary valid compression maps and does not prescribe representation maps, unique-sink orientations or a proof strategy.',importance=dict(score=c['importance']['score'],method='editorial',reason='A sharp structural extension of sample compression, connecting VC dimension with reconstruction from unlabeled points for a broad class beyond maximum systems. Existing score retained.',assessed_on=DATE),working_summary=dict(sentences=['An ample class strongly shatters every set of coordinates that it shatters.','A compressor selects at most d input points from any realizable labeled sample, where d is the class’s VC dimension.','A reconstructor must recover a concept in the original class consistent with all sample labels while receiving only the selected points.','Maximum classes satisfy this exact bound, and labeled compression is known more generally.','The 2024 oriented-matroid results still leave proper unlabeled size-d compression for all ample classes open.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','journal','oriented'])),notes=notes,checked_sources=[r['url'] for r in refs]+['https://arxiv.org/abs/1812.02099v2','https://arxiv.org/abs/2203.11535v4','https://arxiv.org/abs/2110.15168v3'])
